package variablelengthquantity

import (
	"errors"
)

// EncodeVarint encodes a series of uint32 values as variable length
// quantity bytes. Only the low 7 bits of each byte are significant;
// bit 7 (0x80) is set on every byte except the last of each value.
// Groups are emitted most-significant-first.
func EncodeVarint(input []uint32) []byte {
	var out []byte
	for _, v := range input {
		// Collect the 7-bit groups least-significant-first.
		var groups []byte
		for {
			groups = append(groups, byte(v&0x7f))
			v >>= 7
			if v == 0 {
				break
			}
		}
		// Reverse so the most significant group comes first.
		for i, j := 0, len(groups)-1; i < j; i, j = i+1, j-1 {
			groups[i], groups[j] = groups[j], groups[i]
		}
		// Mark every group except the last as continuing.
		for i := 0; i < len(groups)-1; i++ {
			groups[i] |= 0x80
		}
		out = append(out, groups...)
	}
	return out
}

// DecodeVarint decodes variable length quantity bytes back into
// uint32 values. It returns an error if the input ends in the middle
// of a sequence (i.e. the last byte has bit 7 set).
func DecodeVarint(input []byte) ([]uint32, error) {
	var out []uint32
	for i := 0; i < len(input); {
